var nReturnValue = new Number(0);
	if ((typeof(nArray) != 'undefined') && (nArray.constructor == Array))
	{
		for (i = 0; i < nArray.length; i++)
			nReturnValue += nArray[i]-0;		

		return nReturnValue;
	}
	else
	{
		alert("An error occurred during add operation.  Array not initialized.");
		return;
