/* If CrimeInsuringAgreement.Type = "Lessees Of Safe Deposit Boxes", "Employee Theft - Name Schedule", "Employee Theft - Position Schedule" or "Securities Deposited With Others", then disable CrimeInsuringAgreement.Deduct field. 

*/

var CrimeType = document.form1.XPath_Type;
var CrimeDed = document.form1.XPath_Deduct;

if (CrimeType.value == "Lessees Of Safe Deposit Boxes" || CrimeType.value == "Employee Theft - Name Schedule" || CrimeType.value == "Employee Theft - Position Schedule" || CrimeType.value == "Securities Deposited With Others")
  CrimeDed.blur();

//if (CrimeType.value == "Lessees Of Safe Deposit Boxes" || CrimeType.value == "Employee Theft - Name Schedule" || CrimeType.value == Employee Theft - Position Schedule" || CrimeType.value == "Securities Deposited With Others")
  //CrimeDed.onblur;

/*  If CrimeInsuringAgreement.Type <> "Lessees Of Safe Deposit Boxes", "Employee Theft - Name Schedule", "Employee Theft - Position Schedule" or "Securities Deposited With Others" 

AND CrimeInsuringAgreement.Deduct field = "Null", 

then display the message "A Deductible Limit Must Be Entered For the Insuring Agreement Selected." */

var CrimeType = document.form1.XPath_Type;
var CrimeDed = document.form1.XPath_Deduct;

if (CrimeType.value != "Lessees Of Safe Deposit Boxes" && CrimeType.value != "Employee Theft - Name Schedule" && CrimeType.value != "Employee Theft - Position Schedule" && CrimeType.value != "Securities Deposited With Others")
{
  var retval = TextFieldIsBlank(CrimeDed);

  if (retval == "")
  {
    alert("A Deductible Limit Must Be Entered For the Insuring Agreement Selected.");
    CrimeDed.focus();
  }
}

//var func = document.form1.XPath_Deduct.onchange;
//eval(func + "anonymous()");

/* 
Not applicable in VA
Seven table columns, CrisisManagementPct, EmployeeSecurityPct, SecurityConsultantsPct, ScopeOperationsPct, TravelPct, SubsidiaryOperationsPct and UniqueFeaturesPct will be totaled
and stored in the CrimeKidnapRansomExtortionIRPM.TotalModificationPct.  When the TotalModificationPct is < -25% or  > 25%,
display the message "The total credit/debit cannot exceed 25%." Do not reset page field values to 0% when the TotalModificationPct exceeds 25%. 
*/ 
var strCrisisManagementPct = new String(document.form1.XPath_CrisisManagementPct.value); 
var strEmployeeSecurityPct = new String(document.form1.XPath_EmployeeSecurityPct.value); 
var strSecurityConsultantsPct = new String(document.form1.XPath_SecurityConsultantsPct.value);
var strScopeOperationsPct = new String(document.form1.XPath_ScopeOperationsPct.value); 
var strTravelPct = new String(document.form1.XPath_TravelPct.value);
var strSubsidiaryOperationsPct = new String(document.form1.XPath_SubsidiaryOperationsPct.value);
var strUniqueFeaturesPct = new String(document.form1.XPath_UniqueFeaturesPct.value);
var PctTotal; 

//Remove percent symbol from string values 
strCrisisManagementPct = StripPCT(strCrisisManagementPct); 
strEmployeeSecurityPct = StripPCT(strEmployeeSecurityPct); 
strSecurityConsultantsPct = StripPCT(strSecurityConsultantsPct); 
strScopeOperationsPct = StripPCT(strScopeOperationsPct); 
strTravelPct = StripPCT(strTravelPct); 
strSubsidiaryOperationsPct = StripPCT(strSubsidiaryOperationsPct);
strUniqueFeaturesPct = StripPCT(strUniqueFeaturesPct);

//create Array
	var nArray = new Array(7);
	nArray[0] = strCrisisManagementPct;
	nArray[1] = strEmployeeSecurityPct;
	nArray[2] = strSecurityConsultantsPct;
	nArray[3] = strScopeOperationsPct;
	nArray[4] = strTravelPct;
	nArray[5] = strSubsidiaryOperationsPct;
	nArray[6] = strUniqueFeaturesPct;

//Add the numbers together
	PctTotal = AddNumbersInArray(nArray);

//Total must fall within -25 to 25 range
	var nPctTotal = PctTotal - 0;

	if (((nPctTotal > 25) || (nPctTotal < -25)) && (!(bAlerted)))
	{
                //bAlerted controls the display of the message.
                //This flag will toggle as the message so that it is
                //displayed only once
		bAlerted = true;
		alert("The total credit/debit cannot exceed 25%");

	}
	else if((nPctTotal < 25) && (nPctTotal > -25))
	{
		bAlerted = false;
	}

	document.form1.XPath_TotalModificationPct.value = PctTotal;

/* If CrimeInsuringAgreement.Type <> "Lessees Of Safe Deposit Boxes", "Employee Theft - Name Schedule", "Employee Theft - Position Schedule" or "Securities Deposited With Others" AND  CrimeInsuringAgreement.LimitOfIns field = "Null", then display the message "Limit Of Insurance Must Be Entered For Insuring Agreement Selected." 

If CrimeInsuringAgreement.Type <> "Lessees Of Safe Deposit Boxes", "Employee Theft - Name Schedule", "Employee Theft - Position Schedule" or "Securities Deposited With Others" AND  CrimeInsuringAgreement.LimitOfIns field <> "Null", then set focus to CrimeInsuringAgreement.Deduct field. */


var CrimeType = document.form1.XPath_Type;
var InsLimit = document.form1.XPath_LimitOfIns;

if (CrimeType.value != "Lessees Of Safe Deposit Boxes" && CrimeType.value != "Employee Theft - Name Schedule" && CrimeType.value != "Employee Theft - Position Schedule" && CrimeType.value != "Securities Deposited With Others")
{
  var retval = TextFieldIsBlank(InsLimit);

  if (retval == "")
  {
    alert("Limit Of Insurance Must Be Entered For Insuring Agreement Selected.");
    InsLimit.focus();
  }
}

/* 

If CrimeInsuringAgreement.Type <> "Lessees Of Safe Deposit Boxes", "Employee Theft - Name Schedule", "Employee Theft - Position Schedule" or "Securities Deposited With Others", then set focus to CrimeInsuringAgreement.LimitOfIns field.  

If CrimeInsuringAgreement.Type = "Lessees Of Safe Deposit Boxes", "Employee Theft - Name Schedule", "Employee Theft - Position Schedule" or "Securities Deposited With Others", 

then set the CrimeInsuringAgreement.LimitOfIns field and CrimeInsuringAgreement.Deduct field to "0". 
*/

var CrimeType = document.form1.XPath_Type;
var InsLimit  = document.form1.XPath_LimitOfIns;
var CrimeDed  = document.form1.XPath_Deduct;

if (CrimeType.value == "Lessees Of Safe Deposit Boxes" || CrimeType.value == "Employee Theft - Name Schedule" || CrimeType.value == "Employee Theft - Position Schedule" || CrimeType.value == "Securities Deposited With Others")
{ 
  InsLimit.value = 0;
  CrimeDed.value = 0;
}
else 
{
  if (InsLimit.value == 0)
    InsLimit.value = "";
  InsLimit.focus();
}

if (CrimeType.value == "Inside The Premises - Theft Of Money And Securities" || CrimeType.value == "Inside The Premises - Robbery Or Safe Burglary Of Other Property" || CrimeType.value == "Outside The Premises" || CrimeType.value == "Money Orders And Counterfeit Paper Currency" || CrimeType.value == "Inside The Premises - Theft Of Other Property" || CrimeType.value == "Inside The Premises - Robbery Or Safe Burglary Of Money And Securities" || CrimeType.value == "Guests Property" || CrimeType.value == "Safe Depository")
  CrimeDed.value = 0;

/* Five table columns, ClassPct, LocationPct, PersonnelPct, ManagementPct and ProtvFeaturesPct will be totaled
and stored in the CrimeScheduleRatingModification.TotalModificationPct.  When the TotalModificationPct is < -25% or  > 25%,
display the message "The total credit/debit cannot exceed 25%." Do not reset page field values to 0% when the TotalModificationPct exceeds 25%. */ 
var strManagementPct = new String(document.form1.XPath_ManagementPct.value); 
var strLocationPct = new String(document.form1.XPath_LocationPct.value); 
var strProtvFeaturesPct = new String(document.form1.XPath_ProtvFeaturesPct.value);
var strPersonnelPct = new String(document.form1.XPath_PersonnelPct.value); 
var strClassPct = new String(document.form1.XPath_ClassPct.value);
var PctTotal; 

//Remove percent symbol from string values 
strManagementPct = StripPCT(strManagementPct); 
strLocationPct = StripPCT(strLocationPct); 
strProtvFeaturesPct = StripPCT(strProtvFeaturesPct); 
strPersonnelPct = StripPCT(strPersonnelPct); 
strClassPct = StripPCT(strClassPct); 

//create Array
	var nArray = new Array(5);
	nArray[0] = strManagementPct;
	nArray[1] = strLocationPct;
	nArray[2] = strProtvFeaturesPct;
	nArray[3] = strPersonnelPct;
	nArray[4] = strClassPct;


//Add the numbers together
	PctTotal = AddNumbersInArray(nArray);

//Total must fall within -25 to 25 range
	var nPctTotal = PctTotal - 0;

	if (((nPctTotal > 25) || (nPctTotal < -25)))
	{
                //bAlerted controls the display of the message.
                //This flag will toggle as the message so that it is
                //displayed only once
		alert("The total credit/debit cannot exceed 25%");

	}
	else if((nPctTotal < 25) && (nPctTotal > -25))
	{

	}

	document.form1.XPath_TotalModificationPct.value = PctTotal;

